/**
 * Post the pull request announcement to the configured service.
 *
 * Posts the composed announcement (see GET /api/announcement) to the configured service — to the given channel, or the configured one when none is given, or the webhook's own channel. Given the text a preview showed, it posts only that text: when the announcement composed now reads differently (CI turned red, the pull request merged), nothing is posted and the answer is 409, so the caller previews it again. Refused with 409 too when there is no pull request to announce or the server is not running in a git repository, and 422 when the service refuses the post or is not set up. Given mentions, it tags the linked user owners and the groups named on a line after the text; a group the announcement did not offer, or mentions where it tags no one, is a 422 and nothing is posted; a service that cannot be reached, or asks to wait, is a 502. The mentions carry the user IDs the preview showed tagged: when the linked owners read now differ (a link changed in Settings or a terminal since), nothing is posted and the answer is 409, as for changed text. Tagging needs a Slack user token in the configuration in effect at the post. No answer carries the service's own error, which can name the webhook.
 */
export const announce = <ThrowOnError extends boolean = false>(options: Options<AnnounceData, ThrowOnError>): RequestResult<AnnounceResponses, AnnounceErrors, ThrowOnError> => (options.client ?? client).post<AnnounceResponses, AnnounceErrors, ThrowOnError>({
    responseValidator: async (data) => await zAnnounceResponse.parseAsync(data),
    url: '/api/announce',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Push the current branch to its remote, setting upstream.
 *
 * Publishes the checked-out branch to the push remote, setting upstream if it has none — the first outward step of opening a pull request. It is refused with 409 when there is nothing to push (a detached HEAD, or a branch already published on its push remote and not ahead of it there) or the server is not running in a git repository, and 422 when the push fails.
 */
export const push = <ThrowOnError extends boolean = false>(options?: Options<PushData, ThrowOnError>): RequestResult<PushResponses, PushErrors, ThrowOnError> => (options?.client ?? client).post<PushResponses, PushErrors, ThrowOnError>({
    responseValidator: async (data) => await zPushResponse.parseAsync(data),
    url: '/api/push',
    ...options
});

/**
 * Commit the staged changes with a Conventional Commit message.
 *
 * Commits what is already staged, with a message assembled from the Conventional Commit parts and a Refs trailer for the branch's issue. Staging is done elsewhere; this commits the index as it stands. It is refused with 409 when nothing is staged or the server is not running in a git repository, and 422 when the message is not a valid Conventional Commit or the commit (its hooks) fails.
 */
export const commit = <ThrowOnError extends boolean = false>(options: Options<CommitData, ThrowOnError>): RequestResult<CommitResponses, CommitErrors, ThrowOnError> => (options.client ?? client).post<CommitResponses, CommitErrors, ThrowOnError>({
    responseValidator: async (data) => await zCommitResponse.parseAsync(data),
    url: '/api/commit',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * The pull request that would be opened for the branch, for a preview.
 *
 * Composes a pull request for the checked-out branch — a title and body from its commits, the issue, and the repository's template, with the base it would merge into — without opening it, so the browser can edit it before confirming. Answered 409 when there is nothing to open: the tree is not on a branch, the branch has no commits, or a pull request is already open for it; and when the server is not running in a git repository.
 */
export const getPullRequestDraft = <ThrowOnError extends boolean = false>(options?: Options<GetPullRequestDraftData, ThrowOnError>): RequestResult<GetPullRequestDraftResponses, GetPullRequestDraftErrors, ThrowOnError> => (options?.client ?? client).get<GetPullRequestDraftResponses, GetPullRequestDraftErrors, ThrowOnError>({
    responseValidator: async (data) => await zGetPullRequestDraftResponse.parseAsync(data),
    url: '/api/pull-request/draft',
    ...options
});

/**
 * Open a pull request for the current branch, pushing it first if needed.
 *
 * Opens a pull request from the checked-out branch with the given title, body, base, and draft flag. The branch is always the checked-out one, not the caller's to choose; when it is not yet published, it is pushed first, as opening a pull request from an unpushed branch cannot work. Refused with 409 when there is nothing to open (see GET /api/pull-request/draft) or the server is not running in a git repository, and 422 when the push fails, the title or base is missing, the forge turns the pull request down, with the forge's reason, or the repository's forge cannot be told apart, which says to set forge.kind and forge.host. Any other failed open is answered as a read's failure is: 502 when the forge cannot be reached, asks to wait or redirects, 404 when it will not show the repository, and 422 when the forge token is missing or refused, or the forge settings are incomplete or reach no forge API. A reviewer either forge will not take, or an assignee GitLab does not know, does not stop the pull request: it opens with the reviewers and assignees the forge took, and the answer carries a warning.
 */
export const openPullRequest = <ThrowOnError extends boolean = false>(options: Options<OpenPullRequestData, ThrowOnError>): RequestResult<OpenPullRequestResponses, OpenPullRequestErrors, ThrowOnError> => (options.client ?? client).post<OpenPullRequestResponses, OpenPullRequestErrors, ThrowOnError>({
    responseValidator: async (data) => await zOpenPullRequestResponse.parseAsync(data),
    url: '/api/pull-request',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

